document.addEventListener('DOMContentLoaded',()=>{if(typeof Lenis!=='undefined'){const lenis=new Lenis({duration:1.2,easing:(t)=>Math.min(1,1.001-Math.pow(2,-10*t)),direction:'vertical',gestureDirection:'vertical',smooth:!0,mouseMultiplier:1,smoothTouch:!1,touchMultiplier:2,infinite:!1,});function raf(time){lenis.raf(time);requestAnimationFrame(raf)}
requestAnimationFrame(raf)}
if(typeof gsap!=='undefined'){const animateTabContent=(tabId)=>{const tabContent=document.getElementById(tabId);if(!tabContent)return;const cards=tabContent.querySelectorAll('.card, .dior-tab-panel > div');if(cards.length>0){gsap.fromTo(cards,{y:30,opacity:0},{y:0,opacity:1,duration:0.6,stagger:0.05,ease:"power2.out",clearProps:"all"})}};const tabLinks=document.querySelectorAll('[data-tab], [data-bs-toggle="tab"]');tabLinks.forEach(link=>{link.addEventListener('click',(e)=>{let targetId=link.getAttribute('data-tab')||link.getAttribute('href');if(targetId&&targetId.startsWith('#')){targetId=targetId.substring(1)}
if(targetId){setTimeout(()=>animateTabContent(targetId),50)}})});const activeTab=document.querySelector('.dior-tab-panel.active')||document.querySelector('.dior-tab-panel');if(activeTab&&activeTab.id){animateTabContent(activeTab.id)}else{gsap.fromTo(".card",{y:30,opacity:0},{y:0,opacity:1,duration:0.8,stagger:0.1,ease:"power2.out",clearProps:"all"})}}})